def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != background]

    def ranges(length, separators):
        result = []
        start = 0
        for s in separators:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < length:
            result.append((start, length))
        return result

    row_blocks = ranges(h, sep_rows)
    col_blocks = ranges(w, sep_cols)
    if not row_blocks or not col_blocks:
        return [row[:] for row in grid]

    source = None
    best_count = -1
    for ri, (r0, r1) in enumerate(row_blocks):
        for ci, (c0, c1) in enumerate(col_blocks):
            count = sum(grid[r][c] != background
                        for r in range(r0, r1)
                        for c in range(c0, c1))
            if count > best_count:
                best_count = count
                source = (ri, ci, r0, r1, c0, c1)

    sri, sci, sr0, sr1, sc0, sc1 = source
    motif = [grid[r][sc0:sc1] for r in range(sr0, sr1)]
    out = [row[:] for row in grid]

    for ri, (r0, r1) in enumerate(row_blocks):
        for ci, (c0, c1) in enumerate(col_blocks):
            if ri == sri and ci == sci:
                continue
            if r1 - r0 != sr1 - sr0 or c1 - c0 != sc1 - sc0:
                continue
            for dr, row in enumerate(motif):
                out[r0 + dr][c0:c1] = row[:]

    return out
